// Inputs: settings (jsonb map), holds (pending/approved bookings), busy (calendar), request params
const req = $('Slot Request').first().json;
const rules = $('Load Rules').first().json;
const s = rules.settings;
const holds = rules.holds ?? [];
const cal = $input.first().json;
if (cal.ok === false) {
  return [{ json: { ok: false, error: 'calendar_unavailable', slots: [] } }];
}

const tz = s.timezone;
const duration = Number(req.duration_min) === 30 ? 30 : 60;
const buffer = Number(s.buffer_minutes ?? 15);
const step = 30;
const maxSlots = Number(req.max_slots) > 0 ? Number(req.max_slots) : 12;
const workDays = s.work_days ?? [1, 2, 3, 4, 5];
const [wsH, wsM] = String(s.work_start).split(':').map(Number);
const [weH, weM] = String(s.work_end).split(':').map(Number);

const now = DateTime.now().setZone(tz);
const earliest = now.plus({ hours: Number(s.min_notice_hours ?? 4) });
const latest = now.plus({ days: Number(s.max_days_out ?? 30) }).endOf('day');

const fromDay = (req.date_from ? DateTime.fromISO(req.date_from, { zone: tz }) : now).startOf('day');
const toDay = (req.date_to ? DateTime.fromISO(req.date_to, { zone: tz }) : fromDay).startOf('day');

// Busy intervals = calendar busy + held bookings (minus the booking being rescheduled)
const intervals = [];
for (const b of cal.busy ?? []) {
  intervals.push([DateTime.fromISO(b.start, { zone: tz }), DateTime.fromISO(b.end, { zone: tz })]);
}
for (const h of holds) {
  if (req.exclude_booking_id && h.id === req.exclude_booking_id) continue;
  intervals.push([DateTime.fromISO(h.start, { zone: tz }), DateTime.fromISO(h.end, { zone: tz })]);
}
const overlaps = (a0, a1) => intervals.some(([b0, b1]) => a0 < b1 && b0 < a1);

const slots = [];
let rejected = { outside_window: 0, too_soon: 0 };
for (let day = fromDay; day <= toDay; day = day.plus({ days: 1 })) {
  if (day > latest) { rejected.outside_window++; break; }
  if (!workDays.includes(day.weekday)) continue;
  const open = day.set({ hour: wsH, minute: wsM, second: 0, millisecond: 0 });
  const close = day.set({ hour: weH, minute: weM, second: 0, millisecond: 0 });
  for (let start = open; start.plus({ minutes: duration }) <= close; start = start.plus({ minutes: step })) {
    const end = start.plus({ minutes: duration });
    if (start < earliest) { rejected.too_soon++; continue; }
    if (overlaps(start.minus({ minutes: buffer }), end.plus({ minutes: buffer }))) continue;
    slots.push({
      start: start.toISO({ suppressMilliseconds: true }),
      end: end.toISO({ suppressMilliseconds: true }),
      label: start.toFormat("cccc, LLL d 'at' h:mm a") + ' ' + start.toFormat('ZZZZ')
    });
  }
}

// Spread the offered slots across the whole range instead of returning the first N (all mornings)
const total = slots.length;
let offered = slots;
if (total > maxSlots) {
  const stepIdx = (total - 1) / (maxSlots - 1);
  offered = Array.from({ length: maxSlots }, (_, i) => slots[Math.round(i * stepIdx)]);
}

// Exact time the client asked for: checked against ALL open slots, never just the sample
let requested = null;
if (req.check_start) {
  const want = DateTime.fromISO(String(req.check_start), { zone: tz });
  const hit = want.isValid ? slots.find(x => DateTime.fromISO(x.start).toMillis() === want.toMillis()) : null;
  requested = { start: want.isValid ? want.toISO({ suppressMilliseconds: true }) : String(req.check_start), available: Boolean(hit) };
  if (hit && !offered.some(x => x.start === hit.start)) offered = [hit, ...offered.slice(0, Math.max(0, maxSlots - 1))];
}

return [{
  json: {
    ok: true,
    duration_min: duration,
    timezone: tz,
    checked_from: fromDay.toISODate(),
    checked_to: toDay.toISODate(),
    earliest_bookable: earliest.toISO({ suppressMilliseconds: true }),
    latest_bookable_day: latest.toISODate(),
    total_open_slots: total,
    requested_slot_available: requested ? requested.available : null,
    requested_slot: requested,
    slots: offered,
    note: rejected.outside_window > 0 && total === 0
      ? `That date is past the booking window. The latest bookable day is ${latest.toFormat('cccc, LLL d')}.`
      : total === 0
        ? 'No open slots in this range. Offer to check other days.'
        : 'Spread across the range. If the client prefers a time of day, offer the matching ones; offer 2-3, never all.'
  }
}];

